-- Seeded local fixtures are intentionally used by this isolation suite.
begin;
select no_plan();
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.tenant where tenant_id = '10000000-0000-0000-0000-000000000002'), 0::bigint, 'Tenant A admin cannot read tenant B tenant');
select throws_ok('insert into public.tenant (tenant_name, tenant_slug) values (''Blocked tenant'', ''blocked-tenant'')', '42501', null, 'Tenant A admin cannot insert tenant B tenant');
with changed as (update public.tenant set tenant_name = 'Blocked' where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot update tenant B tenant');
with changed as (delete from public.tenant where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot delete tenant B tenant');
select is((select count(*) from public.person where tenant_id = '10000000-0000-0000-0000-000000000002'), 0::bigint, 'Tenant A admin cannot read tenant B person');
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000002'', ''Blocked'', ''Person'')', '42501', null, 'Tenant A admin cannot insert tenant B person');
with changed as (update public.person set person_first_name = 'Blocked' where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot update tenant B person');
with changed as (delete from public.person where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot delete tenant B person');
select is((select count(*) from public.membership where tenant_id = '10000000-0000-0000-0000-000000000002'), 0::bigint, 'Tenant A admin cannot read tenant B membership');
select throws_ok('insert into public.membership (tenant_id, person_id, membership_role) values (''10000000-0000-0000-0000-000000000002'', ''30000000-0000-0000-0000-000000000006'', ''guard'')', '42501', null, 'Tenant A admin cannot insert tenant B membership');
with changed as (update public.membership set membership_status = 'revoked' where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot update tenant B membership');
with changed as (delete from public.membership where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot delete tenant B membership');
select is((select count(*) from public.membership_permission where tenant_id = '10000000-0000-0000-0000-000000000002'), 0::bigint, 'Tenant A admin cannot read tenant B membership_permission');
select throws_ok('insert into public.membership_permission (tenant_id, membership_id, membership_permission_admin_permission) values (''10000000-0000-0000-0000-000000000002'', ''40000000-0000-0000-0000-000000000006'', ''registry'')', '42501', null, 'Tenant A admin cannot insert tenant B membership_permission');
with changed as (update public.membership_permission set membership_permission_admin_permission = 'guards' where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot update tenant B membership_permission');
with changed as (delete from public.membership_permission where tenant_id = '10000000-0000-0000-0000-000000000002' returning 1) select is((select count(*) from changed), 0::bigint, 'Tenant A admin cannot delete tenant B membership_permission');
select is((select count(*) from public.audit_event where tenant_id = '10000000-0000-0000-0000-000000000002'), 0::bigint, 'Tenant A admin cannot read tenant B audit_event');
select throws_ok('insert into public.audit_event (tenant_id, audit_event_action, audit_event_table_name, audit_event_row_id, audit_event_diff) values (''10000000-0000-0000-0000-000000000002'', ''insert'', ''person'', ''30000000-0000-0000-0000-000000000006'', ''{}'')', '42501', null, 'Tenant A admin cannot insert tenant B audit_event');
select throws_ok('update public.audit_event set audit_event_action = ''delete'' where tenant_id = ''10000000-0000-0000-0000-000000000002''', '42501', null, 'Tenant A admin cannot update tenant B audit_event');
select throws_ok('delete from public.audit_event where tenant_id = ''10000000-0000-0000-0000-000000000002''', '42501', null, 'Tenant A admin cannot delete tenant B audit_event');
select is((select count(*) from public.tenant), 1::bigint, 'Tenant admin can read own tenant');
select is((select count(*) from public.person), 5::bigint, 'Registry admin can read all people in own tenant');
select is((select count(*) from public.membership_permission), 9::bigint, 'Registry admin can read own permissions');
select ok((select count(*) > 0 from public.audit_event), 'Access audit admin can read own tenant audit');
select throws_ok('update public.tenant set tenant_subscription_status = ''active'' where tenant_id = ''10000000-0000-0000-0000-000000000001''', '42501', null, 'Tenant settings admin cannot change subscription status');
select throws_ok('update public.person set tenant_id = ''10000000-0000-0000-0000-000000000002'' where person_id = ''30000000-0000-0000-0000-000000000002''', '23514', null, 'Tenant identity cannot change');
select throws_ok('update public.person set person_id = gen_random_uuid() where person_id = ''30000000-0000-0000-0000-000000000002''', '23514', null, 'Primary key cannot change');
select throws_ok('insert into public.membership (tenant_id, person_id, membership_role) values (''10000000-0000-0000-0000-000000000001'', ''30000000-0000-0000-0000-000000000006'', ''guard'')', '23503', null, 'Composite membership FK rejects a cross-tenant person');
select throws_ok('insert into public.membership_permission (tenant_id, membership_id, membership_permission_admin_permission) values (''10000000-0000-0000-0000-000000000001'', ''40000000-0000-0000-0000-000000000006'', ''registry'')', '23514', null, 'Permission assignment rejects a cross-tenant membership');
select throws_ok('insert into public.membership_permission (tenant_id, membership_id, membership_permission_admin_permission) values (''10000000-0000-0000-0000-000000000001'', ''40000000-0000-0000-0000-000000000003'', ''registry'')', '23514', null, 'A guard membership cannot receive admin permissions');
select throws_ok('update public.membership set membership_role = ''guard'' where membership_id = ''40000000-0000-0000-0000-000000000002''', '23514', null, 'An admin with permissions cannot become a guard');
reset role;
select ok(exists(select 1 from pg_constraint where conrelid = 'public.membership_permission'::regclass and contype = 'f' and confrelid = 'public.membership'::regclass and cardinality(conkey) = 2), 'Membership permissions have a composite tenant membership foreign key');
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.person), 5::bigint, 'Guard can read operational people in own tenant');
select is((select count(*) from public.membership), 1::bigint, 'Guard can read only own membership');
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000001'', ''Blocked'', ''Guard'')', '42501', null, 'Guard cannot create people');
select is((select count(*) from public.audit_event), 0::bigint, 'Guard cannot read audit');
reset role;
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000004","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.person), 1::bigint, 'Unit holder can read only own person');
select is((select count(*) from public.membership), 1::bigint, 'Unit holder can read only own membership');
select is((select count(*) from public.membership_permission), 0::bigint, 'Resident 4 cannot read admin permissions');
reset role;
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000005","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.person), 1::bigint, 'Household member can read only own person');
select is((select count(*) from public.membership), 1::bigint, 'Household member can read only own membership');
select is((select count(*) from public.membership_permission), 0::bigint, 'Resident 5 cannot read admin permissions');
reset role;
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000010","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is((select count(*) from public.tenant), 2::bigint, 'Multi-tenant user can read both own tenants');
select is((select count(*) from public.person), 2::bigint, 'Multi-tenant user has separate private person rows');
reset role;
update public.membership set membership_valid_to = now() - interval '1 second' where membership_id = '40000000-0000-0000-0000-000000000002';
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select ok(not app_private.is_tenant_member('10000000-0000-0000-0000-000000000001'), 'expired membership grants no tenant membership');
select ok(not app_private.has_tenant_role('10000000-0000-0000-0000-000000000001', array['tenant_admin']::public.membership_role[]), 'expired membership grants no tenant role');
select ok(not app_private.has_admin_permission('10000000-0000-0000-0000-000000000001', 'registry'), 'expired membership grants no admin permission');
select is((select count(*) from public.tenant), 0::bigint, 'expired membership grants no tenant reads');
select is((select count(*) from public.person), 0::bigint, 'expired membership grants no person reads');
select is((select count(*) from public.membership), 0::bigint, 'expired membership grants no membership reads');
select is((select count(*) from public.membership_permission), 0::bigint, 'expired membership grants no membership_permission reads');
select is((select count(*) from public.audit_event), 0::bigint, 'expired membership grants no audit_event reads');
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000001'', ''Blocked'', ''Inactive'')', '42501', null, 'expired membership grants no registry writes');
reset role;
update public.membership set membership_valid_from = '2020-01-01', membership_valid_to = null, membership_status = 'active' where membership_id = '40000000-0000-0000-0000-000000000002';
