select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select ok(not app_private.is_tenant_member('10000000-0000-0000-0000-000000000001'), 'revoked membership grants no tenant membership');
select ok(not app_private.has_tenant_role('10000000-0000-0000-0000-000000000001', array['tenant_admin']::public.membership_role[]), 'revoked membership grants no tenant role');
select ok(not app_private.has_admin_permission('10000000-0000-0000-0000-000000000001', 'registry'), 'revoked membership grants no admin permission');
select is((select count(*) from public.tenant), 0::bigint, 'revoked membership grants no tenant reads');
select is((select count(*) from public.person), 0::bigint, 'revoked membership grants no person reads');
