select is((select count(*) from public.membership_permission), 0::bigint, 'revoked membership grants no membership_permission reads');
select is((select count(*) from public.audit_event), 0::bigint, 'revoked membership grants no audit_event reads');
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000001'', ''Blocked'', ''Inactive'')', '42501', null, 'revoked membership grants no registry writes');
