update public.membership set membership_valid_from = '2020-01-01', membership_valid_to = null, membership_status = 'active' where membership_id = '40000000-0000-0000-0000-000000000002';
update public.membership set membership_valid_from = now() + interval '1 second', membership_valid_to = null where membership_id = '40000000-0000-0000-0000-000000000002';
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select ok(not app_private.is_tenant_member('10000000-0000-0000-0000-000000000001'), 'future membership grants no tenant membership');
select ok(not app_private.has_tenant_role('10000000-0000-0000-0000-000000000001', array['tenant_admin']::public.membership_role[]), 'future membership grants no tenant role');
select ok(not app_private.has_admin_permission('10000000-0000-0000-0000-000000000001', 'registry'), 'future membership grants no admin permission');
select is((select count(*) from public.tenant), 0::bigint, 'future membership grants no tenant reads');
select is((select count(*) from public.person), 0::bigint, 'future membership grants no person reads');
select is((select count(*) from public.membership), 0::bigint, 'future membership grants no membership reads');
select is((select count(*) from public.membership_permission), 0::bigint, 'future membership grants no membership_permission reads');
select is((select count(*) from public.audit_event), 0::bigint, 'future membership grants no audit_event reads');
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000001'', ''Blocked'', ''Inactive'')', '42501', null, 'future membership grants no registry writes');
