select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select ok(not app_private.is_tenant_member('10000000-0000-0000-0000-000000000001'), 'boundary membership grants no tenant membership');
select ok(not app_private.has_tenant_role('10000000-0000-0000-0000-000000000001', array['tenant_admin']::public.membership_role[]), 'boundary membership grants no tenant role');
select ok(not app_private.has_admin_permission('10000000-0000-0000-0000-000000000001', 'registry'), 'boundary membership grants no admin permission');
select is((select count(*) from public.tenant), 0::bigint, 'boundary membership grants no tenant reads');
select is((select count(*) from public.person), 0::bigint, 'boundary membership grants no person reads');
select is((select count(*) from public.membership), 0::bigint, 'boundary membership grants no membership reads');
select is((select count(*) from public.membership_permission), 0::bigint, 'boundary membership grants no membership_permission reads');
select is((select count(*) from public.audit_event), 0::bigint, 'boundary membership grants no audit_event reads');
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000001'', ''Blocked'', ''Inactive'')', '42501', null, 'boundary membership grants no registry writes');
