select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select throws_ok('insert into public.person (tenant_id, person_first_name, person_last_name) values (''10000000-0000-0000-0000-000000000001'', ''Blocked'', ''Admin'')', '42501', null, 'Admin without registry cannot insert people');
with changed as (update public.person set person_first_name = 'Blocked' where person_id = '30000000-0000-0000-0000-000000000003' returning 1) select is((select count(*) from changed), 0::bigint, 'Admin without registry cannot update people');
with changed as (delete from public.person where person_id = '30000000-0000-0000-0000-000000000003' returning 1) select is((select count(*) from changed), 0::bigint, 'Admin without registry cannot delete people');
reset role;
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}', true);
set local role authenticated;
select is(app_private.is_platform_admin(), false, 'Platform admin requires more than aal1');
select ok((select count(*) = 0 from public.tenant), 'Platform admin at aal1 cannot read tenant');
select ok((select count(*) = 0 from public.platform_admin), 'Platform admin at aal1 cannot read platform_admin');
select ok((select count(*) = 0 from public.person), 'Platform admin at aal1 cannot read person');
select ok((select count(*) = 0 from public.membership), 'Platform admin at aal1 cannot read membership');
select ok((select count(*) = 0 from public.membership_permission), 'Platform admin at aal1 cannot read membership_permission');
select ok((select count(*) = 0 from public.audit_event), 'Platform admin at aal1 cannot read audit_event');
select throws_ok('insert into public.tenant (tenant_name, tenant_slug) values (''Blocked'', ''blocked-platform'')', '42501', null, 'Platform admin without MFA cannot create tenants');
reset role;
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}', true);
set local role authenticated;
select is(app_private.is_platform_admin(), true, 'Platform admin requires and accepts aal2');
select ok((select count(*) > 0 from public.tenant), 'Platform admin at aal2 can read tenant');
select ok((select count(*) > 0 from public.platform_admin), 'Platform admin at aal2 can read platform_admin');
select ok((select count(*) > 0 from public.person), 'Platform admin at aal2 can read person');
select ok((select count(*) > 0 from public.membership), 'Platform admin at aal2 can read membership');
select ok((select count(*) > 0 from public.membership_permission), 'Platform admin at aal2 can read membership_permission');
select ok((select count(*) > 0 from public.audit_event), 'Platform admin at aal2 can read audit_event');
select lives_ok('insert into public.tenant (tenant_name, tenant_slug) values (''Platform test'', ''platform-test'')', 'MFA platform admin can create a tenant');
select lives_ok('update public.tenant set tenant_subscription_status = ''active'' where tenant_slug = ''platform-test''', 'MFA platform admin can change subscription status');
select lives_ok('delete from public.tenant where tenant_slug = ''platform-test''', 'MFA platform admin can delete an empty tenant');
reset role;
update public.platform_admin set platform_admin_is_active = false;
select set_config('request.jwt.claims', '{"sub":"20000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal2"}', true);
set local role authenticated;
select ok(not app_private.is_platform_admin(), 'Inactive platform admin gets no access even with MFA');
reset role;
select set_config('request.jwt.claims', '{}', true);
set local role anon;
select throws_ok('select * from public.tenant', '42501', null, 'Anonymous users cannot read tenant');
select throws_ok('select * from public.platform_admin', '42501', null, 'Anonymous users cannot read platform_admin');
select throws_ok('select * from public.person', '42501', null, 'Anonymous users cannot read person');
select throws_ok('select * from public.membership', '42501', null, 'Anonymous users cannot read membership');
select throws_ok('select * from public.membership_permission', '42501', null, 'Anonymous users cannot read membership_permission');
select throws_ok('select * from public.audit_event', '42501', null, 'Anonymous users cannot read audit_event');
reset role;
select * from finish();
rollback;
